-- OPEN TAB schema: run in a dedicated Supabase project after review.
create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','editor','author');
create type public.content_status as enum ('draft','review','scheduled','published','archived');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'OPEN TAB Contributor',avatar_url text,role public.app_role not null default 'author',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text,parent_id uuid references public.categories(id) on delete set null,sort_order int not null default 0,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.articles(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,excerpt text,content text not null default '',cover_image text,category_id uuid references public.categories(id) on delete set null,author_id uuid references public.profiles(id) on delete set null,status public.content_status not null default 'draft',is_featured boolean not null default false,published_at timestamptz,seo_title text,seo_description text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint published_requires_date check(status<>'published' or published_at is not null));
create index articles_public_feed_idx on public.articles(status,published_at desc);create index articles_category_idx on public.articles(category_id,status,published_at desc);
create table public.tags(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique);
create table public.article_tags(article_id uuid references public.articles(id) on delete cascade,tag_id uuid references public.tags(id) on delete cascade,primary key(article_id,tag_id));
create table public.creators(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,bio text,avatar_url text,channel_url text,created_at timestamptz not null default now());
create table public.videos(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,description text,youtube_id text not null,thumbnail_url text,creator_id uuid references public.creators(id) on delete set null,category_id uuid references public.categories(id) on delete set null,status public.content_status not null default 'draft',published_at timestamptz,created_at timestamptz not null default now());
create table public.newsletter_subscribers(id uuid primary key default gen_random_uuid(),email text not null unique,consent_at timestamptz not null default now(),status text not null default 'active' check(status in ('active','unsubscribed')),created_at timestamptz not null default now());
create table public.comments(id uuid primary key default gen_random_uuid(),article_id uuid not null references public.articles(id) on delete cascade,display_name text not null check(length(display_name) between 1 and 80),body text not null check(length(body) between 1 and 3000),status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz not null default now());
create table public.article_views(id bigint generated always as identity primary key,article_id uuid not null references public.articles(id) on delete cascade,viewed_at timestamptz not null default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references public.profiles(id),action text not null,entity text not null,entity_id text,created_at timestamptz not null default now());
create or replace function public.current_user_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
create or replace function public.has_editor_access() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.current_user_role() in ('admin','editor'),false) $$;
create or replace function public.has_admin_access() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.current_user_role()='admin',false) $$;
alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.articles enable row level security;alter table public.tags enable row level security;alter table public.article_tags enable row level security;alter table public.creators enable row level security;alter table public.videos enable row level security;alter table public.newsletter_subscribers enable row level security;alter table public.comments enable row level security;alter table public.article_views enable row level security;alter table public.audit_logs enable row level security;
create policy "public active categories" on public.categories for select using(is_active or public.has_editor_access());create policy "editors manage categories" on public.categories for all using(public.has_editor_access()) with check(public.has_editor_access());
create policy "read published articles or own/editor" on public.articles for select using((status='published' and published_at<=now()) or public.has_editor_access() or author_id=auth.uid());create policy "authors create drafts" on public.articles for insert with check(author_id=auth.uid() and status in ('draft','review'));create policy "authors edit drafts editors all" on public.articles for update using((author_id=auth.uid() and status in ('draft','review')) or public.has_editor_access()) with check((author_id=auth.uid() and status in ('draft','review')) or public.has_editor_access());create policy "editors delete articles" on public.articles for delete using(public.has_editor_access());
create policy "public read tags" on public.tags for select using(true);create policy "editors manage tags" on public.tags for all using(public.has_editor_access()) with check(public.has_editor_access());create policy "read published article tags" on public.article_tags for select using(exists(select 1 from public.articles a where a.id=article_id and a.status='published' and a.published_at<=now()));create policy "editors manage article tags" on public.article_tags for all using(public.has_editor_access()) with check(public.has_editor_access());
create policy "public read creators" on public.creators for select using(true);create policy "editors manage creators" on public.creators for all using(public.has_editor_access()) with check(public.has_editor_access());create policy "read published videos" on public.videos for select using((status='published' and published_at<=now()) or public.has_editor_access());create policy "editors manage videos" on public.videos for all using(public.has_editor_access()) with check(public.has_editor_access());
create policy "read own profile or editor" on public.profiles for select using(id=auth.uid() or public.has_editor_access());create policy "update own profile" on public.profiles for update using(id=auth.uid() or public.has_admin_access()) with check(id=auth.uid() or public.has_admin_access());
create policy "public subscribe" on public.newsletter_subscribers for insert with check(status='active');create policy "admins manage newsletter" on public.newsletter_subscribers for all using(public.has_admin_access()) with check(public.has_admin_access());create policy "public submit pending comment" on public.comments for insert with check(status='pending');create policy "read approved comments" on public.comments for select using(status='approved');create policy "editors moderate comments" on public.comments for all using(public.has_editor_access()) with check(public.has_editor_access());create policy "public record article view" on public.article_views for insert with check(true);create policy "editors read analytics" on public.article_views for select using(public.has_editor_access());create policy "admins read audit logs" on public.audit_logs for select using(public.has_admin_access());
insert into public.categories(name,slug,sort_order) values('Sports','sports',1),('Celebrities','celebrities',2),('Creators','creators',3),('Entertainment','entertainment',4),('Technology','technology',5),('Business','business',6),('Lifestyle','lifestyle',7),('Education','education',8),('World','world',9),('Videos','videos',10),('Opinions','opinions',11) on conflict(slug) do nothing;
-- IMPORTANT: roles must be assigned only by a trusted project owner in Supabase, never by client-side signup. Configure Storage policies and rate limiting before launch.